Permiten tomar decisiones y repetir bloques de código.

edad = 20
if edad >= 18:
    print("Mayor de edad")
elif edad > 12:
    print("Adolescente")
else:
    print("Niño")

# Bucle For
for i in range(3):
    print("Iteración for:", i)

# Bucle While con control
contador = 0
while contador < 3:
    if contador == 1:
        contador += 1
        continue
    print("Contador while:", contador)
    contador += 1
